hudson.tasks.BatchFile.command:
@echo off
echo ===============================================================
echo [MRP CI/CD] Starting Continuous Integration Build Pipeline
echo ===============================================================

echo [STEP 1] Git Status and Verification
git log -1 --oneline
git status

echo [STEP 2] Compiling and Executing Unit Tests (RechargeServiceTest)...
call .\mvn.cmd clean test -Dtest=RechargeServiceTest
if %ERRORLEVEL% NEQ 0 (
    echo [ERROR] Unit tests failed! Aborting pipeline.
    exit /b %ERRORLEVEL%
)

echo [STEP 3] Executing Selenium Automated E2E Regression Tests...
call .\mvn.cmd test -Dtest=RechargeSeleniumTest
if %ERRORLEVEL% NEQ 0 (
    echo [ERROR] Selenium tests failed! Aborting pipeline.
    exit /b %ERRORLEVEL%
)

echo [STEP 4] Packaging Application Standalone JAR...
call .\mvn.cmd package -DskipTests=true
if %ERRORLEVEL% NEQ 0 (
    echo [ERROR] Packaging failed!
    exit /b %ERRORLEVEL%
)

echo ===============================================================
echo [SUCCESS] CI/CD Build and Tests completed successfully!
echo ===============================================================
